import type { Assumption, EntityGroup, RequestedOperation } from '@developmentfinance/client/wire';
import { sql } from 'drizzle-orm';
import {
    bigint,
    check,
    customType,
    date,
    index,
    integer,
    jsonb,
    pgTable,
    primaryKey,
    text,
    timestamp,
    uniqueIndex,
    type AnyPgColumn,
} from 'drizzle-orm/pg-core';

import { user } from './auth-schema.ts';

// Auth tables (user/session/account/verification) are generated by the
// Better Auth CLI — see auth-schema.ts. Everything app-specific lives here.
export * from './auth-schema.ts';

/**
 * A saved Studio conversation: the whole client document (transcript, widgets
 * with their CSV, activity, pins, layout, theme, notes…) as one JSON
 * document, plus the columns the history list needs without unpacking it.
 * `agentSessionId` is the agent's server-side conversation, so a reopened
 * conversation resumes with its context. It is part of the saved document,
 * which the account rewrites on every save, so it grants nothing. The account
 * a harness conversation belongs to is in `studioSessionOwner`.
 */
export const conversation = pgTable(
    'conversation',
    {
        // Client-minted UUID (the conversation id the Studio already uses).
        id: text('id').primaryKey(),
        userId: text('user_id')
            .notNull()
            .references(() => user.id, { onDelete: 'cascade' }),
        title: text('title').notNull(),
        agentSessionId: text('agent_session_id'),
        turnCount: integer('turn_count').default(0).notNull(),
        data: jsonb('data').notNull(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
        updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
    },
    (table) => [
        index('conversation_user_updated_idx').on(table.userId, table.updatedAt),
        // Owner lookups in src/lib/chat/conversationSave find saves by harness conversation.
        index('conversation_agent_session_idx').on(table.agentSessionId),
    ],
);

export type ConversationRow = typeof conversation.$inferSelect;

/**
 * The account a harness conversation (`agentSessionId`) belongs to, which the
 * Studio proxy (src/lib/studio/studioProxy) reads in its `admit` hook, after
 * the rate limit, on each call that names a conversation
 * (src/lib/studio/studioAccess). A signed-in turn naming it, a save naming
 * it, or a read finding no row inserts the row when none exists
 * (src/lib/chat/conversationSave). The owner is the account behind the
 * oldest saved conversation naming the harness conversation, by
 * `conversation.created_at`, then `id`, and with no such save, the account
 * whose turn or save made the claim. A read with no save writes nothing.
 * Once written, the owner stays, so a save by another account, or the owner's save
 * naming a different harness conversation, leaves it as it was. Deleting the
 * account sets `userId` to null and keeps the row, so the conversation
 * belongs to nobody and the proxy refuses every call about it.
 */
export const studioSessionOwner = pgTable(
    'studio_session_owner',
    {
        agentSessionId: text('agent_session_id').primaryKey(),
        userId: text('user_id').references(() => user.id, { onDelete: 'set null' }),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    },
    (table) => [index('studio_session_owner_user_idx').on(table.userId)],
);

/**
 * A public share: a pruned copy of a conversation (or its canvas, or one
 * card) under a short id, which /s/<id> and /embed/<id> render. The copy is
 * fixed at creation while the owner's conversation keeps evolving.
 */
export const share = pgTable(
    'share',
    {
        // Short URL-safe id (8 chars).
        id: text('id').primaryKey(),
        // Null for a share made without an account, search or Studio.
        userId: text('user_id').references(() => user.id, { onDelete: 'cascade' }),
        // What the link shows: 'conversation' (chat + canvas), 'canvas',
        // 'card', or 'search' (a search result).
        kind: text('kind').notNull(),
        // 'live' or 'snapshot'. A live search share re-runs the stored
        // definitions on every open, and a snapshot serves the bytes captured
        // when the link was made. A live canvas or card share redraws its data
        // cards on current data, and a snapshot shows the stored copy. Null
        // reads as live for kind 'search' (`searchShareMode`) and as snapshot
        // for the other kinds (`isLiveStudioShare`), both in
        // src/lib/chat/shareMode.ts.
        mode: text('mode'),
        conversationId: text('conversation_id'),
        cardId: text('card_id'),
        title: text('title').notNull(),
        data: jsonb('data').notNull(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    },
    (table) => [index('share_user_idx').on(table.userId)],
);

/**
 * One row per part of a search share, in part order: what the user asked
 * (`variable_text`) and the dataset it resolved to — the definition's
 * `spec_id` and `identity`, enough to replay it through `dataset_resubmit`
 * without the language model. `entity_groups` holds the named group each
 * role's entities stand for, keyed by role key, which the replay posts
 * beside the identity. `operations` holds what the question asked
 * of the part beyond its data (empty for none), which the replay carries
 * back so the part keeps its operation strip. A snapshot share also carries
 * the `content_version` it captured and the `artifact_digest` of the file it
 * pinned, which the share's download link serves.
 */
export const shareRef = pgTable(
    'share_ref',
    {
        shareId: text('share_id')
            .notNull()
            .references(() => share.id, { onDelete: 'cascade' }),
        partIndex: integer('part_index').notNull(),
        specId: text('spec_id').notNull(),
        identity: jsonb('identity').notNull(),
        // Null when no role was asked for as a group.
        entityGroups: jsonb('entity_groups').$type<Record<string, EntityGroup>>(),
        variableText: text('variable_text'),
        contentVersion: text('content_version'),
        // Null for a live share and for snapshots stored before the column.
        artifactDigest: text('artifact_digest'),
        operations: jsonb('operations').$type<RequestedOperation[]>().notNull().default([]),
        // The part's assumptions as the response gave them, [] included,
        // which the replay echoes. Null for a share stored before the column.
        assumptions: jsonb('assumptions').$type<Assumption[]>(),
    },
    (table) => [primaryKey({ columns: [table.shareId, table.partIndex] })],
);

export type ShareRefRow = typeof shareRef.$inferSelect;

/**
 * The write token dfo-apis issued for a share a signed-in user made, which
 * the website sends on that user's replace and delete requests
 * (src/lib/chat/shareTokens.ts). The share itself lives in dfo-apis, so
 * `share_id` references no table here. A guest's share has no row and
 * stays as made.
 */
export const shareToken = pgTable('share_token', {
    shareId: text('share_id').primaryKey(),
    userId: text('user_id')
        .notNull()
        .references(() => user.id, { onDelete: 'cascade' }),
    writeToken: text('write_token').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
});

export type ShareTokenRow = typeof shareToken.$inferSelect;

/**
 * A share in dfo-apis that no stored write token could take down: its
 * token was refused when the owner's account was deleted, or the take-down
 * that follows a token the website could not keep failed. `user_id`
 * references no table, so the row outlives the account. An operator takes
 * each share down with dfo-apis' `datasets-maintenance take-down-share
 * <id>` and deletes the row. `reason` is the code the take-down failed with.
 */
export const shareCleanup = pgTable('share_cleanup', {
    shareId: text('share_id').primaryKey(),
    userId: text('user_id').notNull(),
    writeToken: text('write_token').notNull(),
    reason: text('reason').notNull(),
    recordedAt: timestamp('recorded_at', { withTimezone: true }).defaultNow().notNull(),
});

/**
 * One row per (user, roadmap entry) vote: the "Under consideration" items
 * on /data/roadmap, which only signed-in people can vote for. The entry id
 * is the corpus' own, so a re-synced roadmap keeps its votes.
 */
export const roadmapVote = pgTable(
    'roadmap_vote',
    {
        userId: text('user_id')
            .notNull()
            .references(() => user.id, { onDelete: 'cascade' }),
        entryId: text('entry_id').notNull(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    },
    (table) => [
        primaryKey({ columns: [table.userId, table.entryId] }),
        index('roadmap_vote_entry_idx').on(table.entryId),
    ],
);

export type RoadmapVoteRow = typeof roadmapVote.$inferSelect;

export type ShareRow = typeof share.$inferSelect;

/**
 * A feedback submission (POST /api/feedback): the chat's thumbs-up/down box
 * and the site-wide form. Deliberately not referencing `user` — the form is
 * open to signed-out visitors, and `email` is whatever the visitor typed,
 * optional and unverified.
 */
export const feedback = pgTable(
    'feedback',
    {
        id: bigint('id', { mode: 'number' }).generatedAlwaysAsIdentity().primaryKey(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
        message: text('message').notNull(),
        email: text('email'),
        page: text('page'),
        userAgent: text('user_agent'),
    },
    (table) => [
        check('feedback_message_length', sql`char_length(${table.message}) BETWEEN 1 AND 5000`),
        index('feedback_created_at_idx').on(table.createdAt.desc()),
    ],
);

export type FeedbackRow = typeof feedback.$inferSelect;

/**
 * One usage event (see src/lib/events): what was searched, what a Studio
 * turn produced, a sign-in… `name` is dotted (`search.query`), `props` the
 * event's own fields. Identity is loose on purpose: `userId` when signed
 * in (no FK — the row outlives the account), `visitorId` a random
 * browser id otherwise, stored only with consent. `dayVisitor` is the
 * request's daily visitor key (src/lib/events/dayVisitor), null for an event
 * with no browser request or no client address. No IPs, no prompt text.
 */
export const event = pgTable(
    'event',
    {
        id: bigint('id', { mode: 'number' }).generatedAlwaysAsIdentity().primaryKey(),
        createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
        name: text('name').notNull(),
        userId: text('user_id'),
        visitorId: text('visitor_id'),
        dayVisitor: text('day_visitor'),
        page: text('page'),
        props: jsonb('props').$type<Record<string, unknown>>().default({}).notNull(),
    },
    (table) => [
        index('event_created_at_idx').on(table.createdAt.desc()),
        index('event_name_created_at_idx').on(table.name, table.createdAt.desc()),
    ],
);

export type EventRow = typeof event.$inferSelect;

/**
 * One counter per limiter key (src/lib/proxy/limitCounter): the per-address
 * limits on /api and /mcp, the Studio's daily prompt allowances and the
 * hourly caps on sign-in codes sent. `key` names the allowance and the
 * caller (`api:203.0.113.7`, `studio-user:<inbox digest>`,
 * `sign-in-code:<digest>`); `count` is the hits in the window that started
 * at `windowStart`, which ends at `expiresAt`. The next hit after the window
 * ends starts the row over, and a row whose window has ended is deleted
 * within minutes (pruneCounters). Every writer in limitCounter sets
 * `expiresAt`. The default `infinity` marks a row written by a revision that
 * does not set it, and pruneCounters deletes such a row by `windowStart` age.
 */
export const limitCounter = pgTable(
    'limit_counter',
    {
        key: text('key').primaryKey(),
        windowStart: timestamp('window_start', { withTimezone: true }).notNull(),
        count: integer('count').notNull(),
        expiresAt: timestamp('expires_at', { withTimezone: true })
            .notNull()
            .default(sql`'infinity'`),
    },
    (table) => [
        index('limit_counter_window_start_idx').on(table.windowStart),
        index('limit_counter_expires_at_idx').on(table.expiresAt),
    ],
);

const bytea = customType<{ data: Buffer }>({ dataType: () => 'bytea' });

/**
 * The random salt of one UTC day's visitor keys (src/lib/events/dayVisitor).
 * The row for a day is created by the first event of that day, which also
 * deletes every earlier day's row, so once its day has passed a key cannot be
 * recomputed from the live database or linked to another day's. Backups keep
 * a deleted row until they expire.
 */
export const daySalt = pgTable('day_salt', {
    day: date('day', { mode: 'string' }).primaryKey(),
    salt: bytea('salt').notNull(),
});

/**
 * The webmail and disposable email domains, lower case, from the
 * `free-email-domains` package. Every migration run rewrites the table to
 * the package's list (db/webmail-domains.ts), and the
 * `account_daily` view (migration 0020) groups their accounts as
 * `Personal email`.
 */
export const webmailDomain = pgTable('webmail_domain', {
    domain: text('domain').primaryKey(),
});

/** A source a Library artifact credits, with its page when it has one. */
export type LibrarySource = { name: string; url: string | null };

/** One step of how a Library artifact was built: what was done, and the
 *  detail of it when there is more to say. `verb` and `object` are the two
 *  halves of `title` as the card's info panel shows them ("Get", "Gross
 *  national income"); a row that lacks them shows `title` alone. */
export type LibraryStep = {
    title: string;
    detail: string | null;
    verb?: string | null;
    object?: string;
};

/** How recent one published card's data was when it was published, as the
 *  platform wrote it: `dataThrough` is the latest period the data holds
 *  ("2024", "2025-Q2"), and `lastRefreshed` the day its source was last
 *  read. Either is null when the card did not say. */
export type LibraryCardDates = { dataThrough: string | null; lastRefreshed: string | null };

/** How one published card's data source asks to be cited, from the card's
 *  description (`cite.text`, the source's own attribution, and `cite.title`,
 *  the dataset's title). Null for a card whose description gave none. */
export type LibraryCardCite = { text: string; title: string } | null;

/**
 * The Library: Studio and search outputs that DFO staff publish under a
 * citable URL, `/library/<slug>`. `share_id` names the share in dfo-apis that
 * draws the artifact, which the Library creates and owns. `share_write_token`
 * is its owner token, kept in this table. `kind` (`chart`,
 * `table`, `key_number`, `canvas` or `data`) and `mode` (`live` or
 * `snapshot`) follow the share. `publish_key` is the id the publish dialog
 * sends with every try of one publish, so a retry finds the artifact the
 * first try made. `content_title` and `content` are the optional text
 * section the publisher writes. `sources` and `steps` are copied from the
 * published cards' descriptions, `card_dates` holds each published
 * card's data dates in card order, and `card_cites` each card's citation
 * (`LibraryCardCite`) in the same order, so the Library's list, filters and pages
 * read this table alone. `published_by` is null once the publisher's account
 * is deleted, and the artifact stays.
 *
 * A withdrawn artifact keeps its row, so its slug stays taken and its URL
 * shows a withdrawn notice. `withdrawn_at` marks it, and the share is taken
 * down in dfo-apis. The `library_artifact_erase_withdrawn` trigger
 * (migrations 0033 and 0035) erases the publisher's text from any row
 * written with `withdrawn_at` set: `title` and `description` become the
 * empty string, `content_title` and `content` null, `sources`, `steps` and
 * `card_cites` empty, and the topic links are deleted. The slug, kind,
 * mode, dates, `published_by`,
 * `share_id`, `publish_key`, `card_dates` and `replaced_by` stay. An
 * artifact is withdrawn only once its share is gone from dfo-apis or
 * recorded in `share_cleanup`, and the same write clears
 * `share_write_token`.
 *
 * `revision` counts the edits to the text and topics. An edit names the
 * revision it was made from and applies only while the row is at that revision,
 * so an edit from an older read cannot overwrite a newer one.
 *
 * `replaced_by` names the artifact a withdrawn one's address points readers
 * to. Only a withdrawn row holds one, it names another row, and it is null
 * once the replacement's row is deleted. The replacement was published when the
 * pointer was written, and the page follows the chain of replacements to
 * the first published one.
 */
export const libraryArtifact = pgTable(
    'library_artifact',
    {
        id: text('id').primaryKey(),
        slug: text('slug').notNull(),
        publishKey: text('publish_key').notNull(),
        shareId: text('share_id').notNull(),
        shareWriteToken: text('share_write_token'),
        kind: text('kind').notNull(),
        mode: text('mode').notNull(),
        title: text('title').notNull(),
        description: text('description').notNull(),
        contentTitle: text('content_title'),
        content: text('content'),
        sources: jsonb('sources')
            .$type<LibrarySource[]>()
            .notNull()
            .default(sql`'[]'::jsonb`),
        steps: jsonb('steps')
            .$type<LibraryStep[]>()
            .notNull()
            .default(sql`'[]'::jsonb`),
        cardDates: jsonb('card_dates')
            .$type<LibraryCardDates[]>()
            .notNull()
            .default(sql`'[]'::jsonb`),
        cardCites: jsonb('card_cites')
            .$type<LibraryCardCite[]>()
            .notNull()
            .default(sql`'[]'::jsonb`),
        publishedBy: text('published_by').references(() => user.id, { onDelete: 'set null' }),
        publishedAt: timestamp('published_at', { withTimezone: true }).defaultNow().notNull(),
        updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
        revision: integer('revision').notNull().default(0),
        withdrawnAt: timestamp('withdrawn_at', { withTimezone: true }),
        replacedBy: text('replaced_by').references((): AnyPgColumn => libraryArtifact.id, {
            onDelete: 'set null',
        }),
    },
    (table) => [
        uniqueIndex('library_artifact_slug_idx').on(table.slug),
        uniqueIndex('library_artifact_publish_key_idx').on(table.publishKey),
        uniqueIndex('library_artifact_share_id_idx').on(table.shareId),
        check(
            'library_artifact_kind',
            sql`${table.kind} IN ('chart', 'table', 'key_number', 'canvas', 'data')`,
        ),
        check('library_artifact_mode', sql`${table.mode} IN ('live', 'snapshot')`),
        check(
            'library_artifact_replaced_by_withdrawn',
            sql`${table.replacedBy} IS NULL OR ${table.withdrawnAt} IS NOT NULL`,
        ),
        check(
            'library_artifact_replaced_by_other',
            sql`${table.replacedBy} IS NULL OR ${table.replacedBy} <> ${table.id}`,
        ),
        index('library_artifact_published_at_idx').on(table.publishedAt.desc()),
    ],
);

export type LibraryArtifactRow = typeof libraryArtifact.$inferSelect;

/** A topic tag the Library's artifacts are filed under. Admins add topics,
 *  and publishers pick from them. A label is unique in any case. */
export const libraryTopic = pgTable(
    'library_topic',
    {
        id: text('id').primaryKey(),
        label: text('label').notNull(),
    },
    (table) => [uniqueIndex('library_topic_label_idx').on(sql`lower(${table.label})`)],
);

/** Which topics each artifact is filed under. */
export const libraryArtifactTopic = pgTable(
    'library_artifact_topic',
    {
        artifactId: text('artifact_id')
            .notNull()
            .references(() => libraryArtifact.id, { onDelete: 'cascade' }),
        topicId: text('topic_id')
            .notNull()
            .references(() => libraryTopic.id, { onDelete: 'cascade' }),
    },
    (table) => [
        primaryKey({ columns: [table.artifactId, table.topicId] }),
        index('library_artifact_topic_topic_idx').on(table.topicId),
    ],
);
